 void Field(TextBox t,int x,int y,int w,string v,Control p=null){t.SetBounds(x,y,w,28);t.Text=v;t.BackColor=Theme.Panel2;t.ForeColor=Theme.Text;t.TextAlign=(t==start||t==stop)?HorizontalAlignment.Center:HorizontalAlignment.Left;(p??this).Controls.Add(t);}Button SB(Control p,string t,int x,int y,int w,EventHandler e){var q=Theme.Button(t);q.SetBounds(x,y,w,36);q.Click+=e;p.Controls.Add(q);return q;}void AB(string t,int x,int y,int w,EventHandler e){SB(this,t,x,y,w,e).Height=39;}
 void Add(string c,string a,string d){int i=g.Rows.Add(c,a,d);g.ClearSelection();g.Rows[i].Selected=true;g.CurrentCell=g.Rows[i].Cells[1];}List<MacroRow> Rows(){var r=new List<MacroRow>();foreach(DataGridViewRow x in g.Rows)r.Add(new MacroRow{command=""+x.Cells[0].Value,argument=""+x.Cells[1].Value,description=""+x.Cells[2].Value});return r;}
 void Pick(string c,string d){using(var x=new KeyPickerDialog())if(x.ShowDialog(FindForm())==DialogResult.OK)Add(c,x.SelectedKey,d);}void Mouse(object s,EventArgs e){var m=new ContextMenuStrip();foreach(var x in new[]{"LEFT|Ліва кнопка","RIGHT|Права кнопка","MIDDLE|Коліщатко"}){var z=x.Split('|');var i=new ToolStripMenuItem(z[1]);string v=z[0];i.Click+=(a,b)=>Add("CLICK",v,"Клік миші");m.Items.Add(i);}m.Show((Control)s,0,((Control)s).Height);}
 void Pixel(string c){if(MessageBox.Show("Після OK програма сховається. У вас буде 3 секунди, щоб навести курсор.","Захоплення пікселя",MessageBoxButtons.OKCancel)!=DialogResult.OK)return;var f=FindForm();f.Hide();Point p;Color q;try{Thread.Sleep(3000);p=MacroNative.Cursor();q=MacroNative.Pixel(p.X,p.Y);}finally{f.Show();f.Activate();}string h=ColorTranslator.ToHtml(q),a=c=="WAITCOLOR"?string.Format("{0} {1} {2} 10 10000",p.X,p.Y,h):string.Format("{0} {1} {2} 10",p.X,p.Y,h);Add(c,a,c=="WAITCOLOR"?"Чекати появи кольору":c=="IFCOLOR"?"Якщо колір збігається":"Якщо колір НЕ збігається");Status("ЗАХОПЛЕНО: "+p.X+", "+p.Y+" · "+h,Theme.Cyan);}
 void MoveRow(int d){if(g.CurrentRow==null)return;int i=g.CurrentRow.Index,j=i+d;if(j<0||j>=g.Rows.Count)return;object[] v={g.Rows[i].Cells[0].Value,g.Rows[i].Cells[1].Value,g.Rows[i].Cells[2].Value};g.Rows.RemoveAt(i);g.Rows.Insert(j,v);g.Rows[j].Selected=true;}
 Keys Hot(TextBox b,string n){string v=b.Text.Trim().ToUpperInvariant();if(v.Length==1&&char.IsDigit(v[0]))v="D"+v;Keys k;if(!Enum.TryParse(v,true,out k)||k==Keys.None)throw new InvalidOperationException("Невідома клавіша "+n+": "+b.Text);b.Text=v.Length==2&&v[0]=='D'?v.Substring(1):v;return k;}void Hotkeys(){if(Hot(start,"запуску")==Hot(stop,"зупинки"))throw new InvalidOperationException("Старт і стоп мають бути різними.");stopBtn.Text="■ СТОП · "+stop.Text;}
 void Check(){try{Hotkeys();var x=MacroCompiler.Compile(Rows());if(x.Count==0)throw new InvalidOperationException("Додайте дію.");Status("СЦЕНАРІЙ КОРЕКТНИЙ\nКоманд: "+x.Count,Theme.Cyan);}catch(Exception e){Status(e.Message,Color.IndianRed);}}void New(){if(running)return;name.Text="Новий макрос";start.Text="F10";stop.Text="F12";g.Rows.Clear();Status("НОВИЙ СЦЕНАРІЙ",Theme.Cyan);}string HK(TextBox b){string v=b.Text.Trim().ToUpperInvariant();return v.Length==1&&char.IsDigit(v[0])?"D"+v:v;}
 void Save(){try{Hotkeys();MacroCompiler.Compile(Rows());string n=Safe(name.Text);JsonFiles.Write(Path.Combine(AppPaths.Macros,n+".json"),new MacroFile{schemaVersion=4,name=n,targetProcess=target.Text,startHotkey=HK(start),stopHotkey=HK(stop),steps=Rows()});Status("ЗБЕРЕЖЕНО",Theme.Cyan);}catch(Exception e){Status(e.Message,Color.IndianRed);}}void Open(){using(var d=new OpenFileDialog()){d.InitialDirectory=AppPaths.Macros;d.Filter="Macro (*.json)|*.json";if(d.ShowDialog()!=DialogResult.OK)return;try{var f=JsonFiles.Read<MacroFile>(d.FileName);name.Text=f.name;target.Text=f.targetProcess;start.Text=Show(f.startHotkey,"F10");stop.Text=Show(f.stopHotkey,"F12");g.Rows.Clear();foreach(var r in f.steps)Add(r.command,r.argument,r.description);Hotkeys();Status("ВІДКРИТО",Theme.Cyan);}catch(Exception e){Status(e.Message,Color.IndianRed);}}}
 void Run(){if(running)return;try{Hotkeys();var x=MacroCompiler.Compile(Rows());if(x.Count==0)throw new InvalidOperationException("Додайте дію.");running=true;Status("СТАРТ ЧЕРЕЗ 0.5 С",Theme.GoldSoft);new Thread(()=>{try{Thread.Sleep(500);runner.Run(x,target.Text,focus.Checked);BeginInvoke((Action)(()=>Status("ВИКОНАННЯ ЗАВЕРШЕНО",Theme.Cyan)));}catch(Exception e){BeginInvoke((Action)(()=>Status(e.Message,Color.IndianRed)));}finally{running=false;}}){IsBackground=true}.Start();}catch(Exception e){running=false;Status(e.Message,Color.IndianRed);}}void Stop(string s){runner.Stop();running=false;Status(s,Color.IndianRed);}void Poll(){Keys a,b;try{a=Hot(start,"запуску");b=Hot(stop,"зупинки");}catch{return;}bool n=(MacroNative.GetAsyncKeyState((int)a)&0x8000)!=0,x=(MacroNative.GetAsyncKeyState((int)b)&0x8000)!=0;if(n&&!sd&&!running)Run();if(x&&!xd&&running)Stop("АВАРІЙНО ЗУПИНЕНО");sd=n;xd=x;}void Status(string s,Color c){status.Text=s;status.ForeColor=c;}static string Safe(string s){foreach(char c in Path.GetInvalidFileNameChars())s=s.Replace(c,'_');return string.IsNullOrWhiteSpace(s)?"Новий макрос":s.Trim();}static string Show(string s,string d){if(string.IsNullOrWhiteSpace(s))s=d;return s.Length==2&&s[0]=='D'?s.Substring(1):s;}public void OnActivated(){}
