internal sealed class KeyPickerDialog:Form{public string SelectedKey{get;private set;}public KeyPickerDialog(){Text="Оберіть клавішу";ClientSize=new Size(825,380);StartPosition=FormStartPosition.CenterParent;BackColor=Theme.Ink;BackgroundImage=AssetImages.Load("summer","macros.jpg");BackgroundImageLayout=ImageLayout.Stretch;string[][] rows={new[]{"Escape","F1","F2","F3","F4","F5","F6","F7","F8","F9","F10","F11","F12"},new[]{"D1","D2","D3","D4","D5","D6","D7","D8","D9","D0","Back","Tab"},new[]{"Q","W","E","R","T","Y","U","I","O","P","Return"},new[]{"A","S","D","F","G","H","J","K","L","Space"},new[]{"Z","X","C","V","B","N","M","Left","Up","Down","Right"},new[]{"LControlKey","LShiftKey","LMenu","RMenu","RShiftKey","RControlKey"}};for(int r=0;r<rows.Length;r++){int x=15;foreach(string k in rows[r]){int w=k=="Space"?220:(k.Contains("Control")||k.Contains("Shift")||k=="Back"||k=="Return")?75:55;var b=Theme.Button(Cap(k));b.SetBounds(x,18+r*58,w,44);string v=k;b.Click+=(s,e)=>{SelectedKey=v;DialogResult=DialogResult.OK;Close();};Controls.Add(b);x+=w+6;}}}static string Cap(string k){if(k=="Escape")return"Esc";if(k=="Back")return"⌫";if(k=="Return")return"Enter";if(k=="Space")return"ПРОБІЛ";if(k=="Left")return"←";if(k=="Up")return"↑";if(k=="Down")return"↓";if(k=="Right")return"→";if(k.Contains("Control"))return"Ctrl";if(k.Contains("Shift"))return"Shift";if(k.Contains("Menu"))return"Alt";return k.Length==2&&k[0]=='D'?k.Substring(1):k;}}
